63	const MAX_DIFF_FILES = 40;
64	const MAX_PATCH_CHARS = 6000;
65	// Larger than any realistic single secret match, so a secret sitting right at the truncation
66	// cut is still fully visible to redact() before that cut is made; bounds the pre-redaction
67	// window so redact() never scans an arbitrarily large patch from an untrusted clone.
68	const SAFETY_MARGIN = 8192;
69	const SHA_RE = /^[0-9a-f]{40}([0-9a-f]{24})?$/;
70	
71	/** Returns the redacted patch text for every file changed by `sha`, keyed by path, each capped at 6000 characters. */
72	export async function getDiff(repoDir: string, sha: string): Promise<Record<string, string>> {
73	  if (!SHA_RE.test(sha)) return {};
74	  let out: string;
75	  try {
76	    out = await git(repoDir, ['diff-tree', '-p', '--no-color', '--no-commit-id', '--root', sha]);
77	  } catch {
78	    return {};
79	  }
80	
81	  const result: Record<string, string> = {};
82	  const chunks = out.split(/(?=^diff --git )/m).filter((c) => c.startsWith('diff --git'));
83	  for (const chunk of chunks.slice(0, MAX_DIFF_FILES)) {
84	    const headerMatch = /^diff --git a\/(.+?) b\/(.+?)$/m.exec(chunk);
85	    const path = headerMatch?.[2];
86	    if (!path) continue;
87	    const bounded = chunk.length <= MAX_PATCH_CHARS + SAFETY_MARGIN ? chunk : chunk.slice(0, MAX_PATCH_CHARS + SAFETY_MARGIN);
88	    result[path] = redactBounded(bounded).text.slice(0, MAX_PATCH_CHARS);
89	  }
90	  return result;
91	}
