  const leakyCommand =
    "cd /Users/peytonmontei/Documents/entire/devenv/entireio/cli/.worktrees/review-child-context && " +
    'perl -0pi -e \'s/"github.com\\/entireio\\/cli\\/internal\\/coreapi"//\' foo.go && go test ./...';
